<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/layout.php';$user=require_login();
$configurationId=filter_input(INPUT_GET,'configuration',FILTER_VALIDATE_INT);$team=null;
try{if($configurationId)$team=(new BusinessRepository(db()))->configuration($configurationId,(int)$user['id']);}catch(PDOException $error){error_log($error->getMessage());render_database_unavailable();}
if(isset($_GET['configuration']) && !$team)render_not_found();
$plan=is_string($_GET['plan'] ?? null)&&isset(plan_definitions()[$_GET['plan']])?$_GET['plan']:'business';
$old=$_SESSION['request_old'] ?? [];unset($_SESSION['request_old']);
$values=array_merge(['company'=>'','contact_email'=>$user['email'],'sector'=>'otro','objective'=>'','plan'=>$plan,'message'=>''],$team?['sector'=>$team['sector'],'objective'=>$team['objective'],'plan'=>$team['plan']]:[],array_filter($old,'is_string'));
if(!isset(plan_definitions()[$values['plan']]))$values['plan']='business';
render_header('Solicitar propuesta');
?>
<section class="page-heading"><p class="eyebrow">EMPIEZA POR TU OBJETIVO</p><h1>Hablemos de tu próximo equipo.</h1><p>Registra lo que necesita tu empresa y el plan que te interesa. La solicitud aparecerá en tu espacio personal.</p></section>
<div class="builder-layout"><form class="panel stack-form" method="post" action="<?= e(url('actions.php')) ?>" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="request_create"><input type="hidden" name="configuration_id" value="<?= (int)$configurationId ?>"><div class="form-row"><label class="field"><span>Empresa</span><input name="company" minlength="2" maxlength="120" value="<?= e($values['company']) ?>" autocomplete="organization" required></label><label class="field"><span>Correo de contacto</span><input name="contact_email" type="email" maxlength="190" value="<?= e($values['contact_email']) ?>" autocomplete="email" required></label></div><div class="form-row"><label class="field"><span>Sector</span><select name="sector"><?php foreach(sector_labels() as $key=>$label): ?><option value="<?= e($key) ?>" <?= $values['sector']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label class="field"><span>Plan de referencia</span><select name="plan"><?php foreach(plan_definitions() as $key=>$definition): ?><option value="<?= e($key) ?>" <?= $values['plan']===$key?'selected':'' ?>><?= e($definition['name'].' · '.$definition['price']) ?></option><?php endforeach; ?></select></label></div><label class="field"><span>Qué necesitas conseguir</span><textarea name="objective" minlength="20" maxlength="2000" rows="4" required data-count><?= e($values['objective']) ?></textarea></label><label class="field"><span>Información adicional · opcional</span><textarea name="message" maxlength="2000" rows="4" data-count placeholder="Plazos, herramientas actuales o preguntas sobre la propuesta."><?= e($values['message']) ?></textarea></label><p class="field-help">Demostración académica: el formulario guarda una solicitud en MySQL. No envía correos, contrata servicios ni realiza cobros. Utiliza datos de ejemplo para probarlo.</p><div class="form-actions"><button class="button" type="submit">Registrar solicitud ↗</button><a class="text-link" href="<?= e(url('dashboard.php')) ?>">Volver a mi espacio</a></div></form><aside class="panel team-summary"><p class="eyebrow"><?= $team?'EQUIPO ASOCIADO':'TU PRÓXIMO PASO' ?></p><h2><?= e($team['name'] ?? 'Una propuesta con contexto.') ?></h2><?php if($team): ?><ol class="selected-list"><?php foreach($team['agents'] as $agent): ?><li><?= e($agent['name']) ?></li><?php endforeach; ?></ol><a class="text-link" href="<?= e(url('builder.php?id='.$configurationId)) ?>">Revisar equipo ↗</a><?php else: ?><p>También puedes diseñar primero una combinación de agentes y asociarla a tu solicitud.</p><a class="button outline" href="<?= e(url('builder.php?plan='.$values['plan'])) ?>">Diseñar un equipo ↗</a><?php endif; ?><p class="field-help">Los precios son orientativos. El alcance, las integraciones y el consumo de IA se definirían en una propuesta real.</p></aside></div>
